package com.quincaisoft.purchasing.application;
import com.quincaisoft.purchasing.api.PurchasingService;import com.quincaisoft.purchasing.infrastructure.*;import com.quincaisoft.purchasing.domain.PurchaseRules;import com.quincaisoft.suppliers.api.SupplierService;import com.quincaisoft.catalog.api.CatalogService;import com.quincaisoft.inventory.api.StockService;import com.quincaisoft.finance.api.FinanceService;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.nio.charset.StandardCharsets;
@Service public class DefaultPurchasingService implements PurchasingService {
 private final EntityManager em;private final ScopedTransactions tx;private final SupplierService suppliers;private final CatalogService catalog;private final StockService stock;private final FinanceService finance;private final OperationJournal operations;
 public DefaultPurchasingService(EntityManager em,ScopedTransactions tx,SupplierService suppliers,CatalogService catalog,StockService stock,FinanceService finance,JsonMapper json){this.em=em;this.tx=tx;this.suppliers=suppliers;this.catalog=catalog;this.stock=stock;this.finance=finance;this.operations=new OperationJournal(em,json);}
 private PurchaseEntity find(UUID id,boolean lock){var s=TenantContext.current();var r=em.find(PurchaseEntity.class,new PurchaseEntity.Key(s.tenantId(),s.companyId(),id),lock?LockModeType.PESSIMISTIC_WRITE:LockModeType.NONE);if(r==null||!r.branchId.equals(s.branchId()))throw new NoSuchElementException("Purchase not found");return r;}
 private List<PurchaseLineEntity> lines(UUID id){return em.createQuery("select l from PurchaseLineEntity l where l.purchaseId=:id order by l.id",PurchaseLineEntity.class).setParameter("id",id).getResultList();}
 private Purchase view(PurchaseEntity r){return new Purchase(r.id,r.supplierId,r.warehouseId,r.businessDate,r.status,r.version,Long.toString(r.totalXaf),lines(r.id).stream().map(l->new Line(l.id,l.productId,Long.toString(l.quantityMilli),Long.toString(l.receivedMilli),Long.toString(l.unitPriceXaf),Long.toString(l.totalXaf))).toList());}
 public List<Purchase> list(){return tx.execute(()->em.createQuery("select p from PurchaseEntity p order by p.businessDate desc,p.id",PurchaseEntity.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Purchase get(UUID id){return tx.execute(()->view(find(id,false)));}
 public Purchase draft(Draft q){if(q==null||q.supplierId()==null||q.warehouseId()==null||q.businessDate()==null||q.lines()==null||q.lines().isEmpty()||q.lines().size()>500)throw new IllegalArgumentException("Supplier, warehouse, date and lines required");return tx.execute(()->operations.once(q.operationId(),"PO_DRAFT|"+q,"PurchaseDrafted",Purchase.class,()->{suppliers.requireEligible(q.supplierId());stock.requireWarehouse(q.warehouseId());var scope=TenantContext.current();var r=new PurchaseEntity();r.tenantId=scope.tenantId();r.companyId=scope.companyId();r.branchId=scope.branchId();r.id=UUID.randomUUID();r.supplierId=q.supplierId();r.warehouseId=q.warehouseId();r.createdBy=scope.actorId();r.businessDate=q.businessDate();r.status="DRAFT";var pending=new ArrayList<PurchaseLineEntity>();var seen=new HashSet<UUID>();for(var i:q.lines()){if(i==null||i.productId()==null||!seen.add(i.productId()))throw new IllegalArgumentException("One line per product required");var p=catalog.get(i.productId());if(!p.active()||p.taxBasisPoints()!=0)throw new IllegalArgumentException("Only active zero-tax products supported");var l=new PurchaseLineEntity();l.tenantId=r.tenantId;l.companyId=r.companyId;l.branchId=r.branchId;l.id=UUID.randomUUID();l.purchaseId=r.id;l.productId=p.id();l.quantityMilli=PurchaseRules.positive(i.quantityMilli());l.unitPriceXaf=PurchaseRules.positive(i.unitPriceXaf());l.totalXaf=PurchaseRules.amount(l.quantityMilli,l.unitPriceXaf);r.totalXaf=Math.addExact(r.totalXaf,l.totalXaf);pending.add(l);}em.persist(r);em.flush();pending.forEach(em::persist);em.flush();return view(r);},Purchase::id));}
 private void version(PurchaseEntity r,long expected){if(r.version!=expected)throw new RevisionConflict("Purchase changed; refresh before retry");}
 public Purchase submit(UUID id,Decision q){return decide(id,q,false);}public Purchase approve(UUID id,Decision q){return decide(id,q,true);}
 private Purchase decide(UUID id,Decision q,boolean approve){PurchaseRules.reason(q.reason());return tx.execute(()->operations.once(q.operationId(),(approve?"PO_APPROVE|":"PO_SUBMIT|")+id+"|"+q,"PurchaseDecision",Purchase.class,()->{var r=find(id,true);version(r,q.version());if(!r.status.equals(approve?"IN_REVIEW":"DRAFT"))throw new IllegalStateException("Invalid order state");if(approve){if(r.createdBy.equals(TenantContext.current().actorId()))throw new IllegalStateException("A different person must approve the order");suppliers.requireEligible(r.supplierId);r.approvedBy=TenantContext.current().actorId();}r.status=approve?"APPROVED":"IN_REVIEW";r.version=Math.incrementExact(r.version);em.flush();return view(r);},Purchase::id));}
 private Receipt receiptView(ReceiptEntity r){var ls=em.createQuery("select l from ReceiptLineEntity l where l.receiptId=:id order by l.id",ReceiptLineEntity.class).setParameter("id",r.id).getResultList();return new Receipt(r.id,r.purchaseId,r.businessDate,Long.toString(r.totalXaf),ls.stream().map(l->new ReceiptLine(l.id,l.purchaseLineId,l.productId,Long.toString(l.quantityMilli),Long.toString(l.valueXaf))).toList());}
 public List<Receipt> receipts(UUID id){return tx.execute(()->{find(id,false);return em.createQuery("select r from ReceiptEntity r where r.purchaseId=:id order by r.businessDate,r.id",ReceiptEntity.class).setParameter("id",id).getResultList().stream().map(this::receiptView).toList();});}
 public Receipt receive(UUID id,Receive q){PurchaseRules.reason(q.reason());if(q.businessDate()==null||q.lines()==null||q.lines().isEmpty()||q.lines().size()>500)throw new IllegalArgumentException("Date and receipt lines required");return tx.execute(()->operations.once(q.operationId(),"PO_RECEIVE|"+id+"|"+q,"GoodsReceived",Receipt.class,()->{var order=find(id,true);version(order,q.version());if(!Set.of("APPROVED","PARTIALLY_RECEIVED").contains(order.status))throw new IllegalStateException("Approved order required");if(q.businessDate().isBefore(order.businessDate))throw new IllegalArgumentException("Receipt cannot precede order");suppliers.requireEligible(order.supplierId);var all=lines(id);var map=new HashMap<UUID,PurchaseLineEntity>();all.forEach(l->map.put(l.id,l));var scope=TenantContext.current();var r=new ReceiptEntity();r.tenantId=scope.tenantId();r.companyId=scope.companyId();r.branchId=scope.branchId();r.id=UUID.randomUUID();r.purchaseId=id;r.operationId=q.operationId();r.actorId=scope.actorId();r.businessDate=q.businessDate();r.reason=q.reason();var pending=new ArrayList<ReceiptLineEntity>();var seen=new HashSet<UUID>();for(var i:q.lines()){if(i==null||!seen.add(i.lineId())||!map.containsKey(i.lineId()))throw new IllegalArgumentException("Unique original purchase lines required");var source=map.get(i.lineId());long qty=PurchaseRules.positive(i.quantityMilli());source.receivedMilli=PurchaseRules.receive(source.quantityMilli,source.receivedMilli,qty);long value=PurchaseRules.amount(qty,source.unitPriceXaf);var l=new ReceiptLineEntity();l.tenantId=r.tenantId;l.companyId=r.companyId;l.branchId=r.branchId;l.id=UUID.randomUUID();l.receiptId=r.id;l.purchaseLineId=source.id;l.productId=source.productId;l.quantityMilli=qty;l.valueXaf=value;r.totalXaf=Math.addExact(r.totalXaf,value);pending.add(l);}em.persist(r);em.flush();for(var l:pending){em.persist(l);stock.receive(order.warehouseId,l.productId,l.quantityMilli,l.valueXaf,UUID.nameUUIDFromBytes((q.operationId()+":"+l.purchaseLineId).getBytes(StandardCharsets.UTF_8)),q.reason());}finance.post(r.id,q.operationId(),q.businessDate(),"PURCHASE_RECEIPT",List.of(new FinanceService.Entry("MERCHANT_INVENTORY",r.totalXaf,0),new FinanceService.Entry("GOODS_RECEIVED_NOT_INVOICED",0,r.totalXaf)));order.status=all.stream().allMatch(l->l.receivedMilli==l.quantityMilli)?"RECEIVED":"PARTIALLY_RECEIVED";order.version=Math.incrementExact(order.version);em.flush();return receiptView(r);},Receipt::id));}
 private Invoice invoiceView(InvoiceEntity r){return new Invoice(r.id,r.receiptId,r.supplierId,r.supplierReference,r.businessDate,Long.toString(r.totalXaf));}
 public List<Invoice> invoices(){return tx.execute(()->em.createQuery("select i from InvoiceEntity i order by i.businessDate desc,i.id",InvoiceEntity.class).setMaxResults(200).getResultList().stream().map(this::invoiceView).toList());}
 public Invoice invoice(UUID receiptId,InvoiceRequest q){PurchaseRules.reason(q.reason());if(q.businessDate()==null||q.supplierReference()==null||q.supplierReference().isBlank()||q.supplierReference().length()>100)throw new IllegalArgumentException("Invoice date and supplier reference required");return tx.execute(()->operations.once(q.operationId(),"SUPPLIER_INVOICE|"+receiptId+"|"+q,"SupplierInvoicePosted",Invoice.class,()->{var s=TenantContext.current();var receipt=em.find(ReceiptEntity.class,new ReceiptEntity.Key(s.tenantId(),s.companyId(),receiptId));if(receipt==null||!receipt.branchId.equals(s.branchId()))throw new NoSuchElementException("Receipt not found");var order=find(receipt.purchaseId,true);suppliers.requireEligible(order.supplierId);if(!supplierReturns(receiptId).isEmpty())throw new IllegalStateException("Returned receipt needs net supplier invoice reconciliation before invoicing");if(q.businessDate().isBefore(receipt.businessDate))throw new IllegalArgumentException("Invoice cannot precede receipt");if(!em.createQuery("select i from InvoiceEntity i where i.receiptId=:r",InvoiceEntity.class).setParameter("r",receiptId).getResultList().isEmpty())throw new IllegalStateException("Receipt already invoiced");var r=new InvoiceEntity();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.receiptId=receiptId;r.supplierId=order.supplierId;r.operationId=q.operationId();r.actorId=s.actorId();r.businessDate=q.businessDate();r.totalXaf=receipt.totalXaf;r.supplierReference=q.supplierReference();r.reason=q.reason();em.persist(r);var balance=new PayableBalance();balance.tenantId=r.tenantId;balance.companyId=r.companyId;balance.branchId=r.branchId;balance.id=r.id;balance.supplierId=r.supplierId;balance.originalXaf=r.totalXaf;em.persist(balance);finance.post(r.id,q.operationId(),r.businessDate,"SUPPLIER_INVOICE",List.of(new FinanceService.Entry("GOODS_RECEIVED_NOT_INVOICED",r.totalXaf,0),new FinanceService.Entry("ACCOUNTS_PAYABLE",0,r.totalXaf)));em.flush();return invoiceView(r);},Invoice::id));}
 private SupplierReturn returnView(SupplierReturnEntity r){return new SupplierReturn(r.id,r.receiptId,r.businessDate,Long.toString(r.totalXaf));}
 public List<SupplierReturn> supplierReturns(UUID id){return tx.execute(()->em.createQuery("select r from SupplierReturnEntity r where r.receiptId=:id order by r.businessDate,r.id",SupplierReturnEntity.class).setParameter("id",id).getResultList().stream().map(this::returnView).toList());}
 public SupplierReturn returnToSupplier(UUID receiptId,ReturnRequest q){PurchaseRules.reason(q.reason());if(q.businessDate()==null||q.lines()==null||q.lines().isEmpty()||q.lines().size()>500)throw new IllegalArgumentException("Date and returned receipt lines required");return tx.execute(()->operations.once(q.operationId(),"SUPPLIER_RETURN|"+receiptId+"|"+q,"SupplierReturned",SupplierReturn.class,()->{
 var scope=TenantContext.current();var receipt=em.find(ReceiptEntity.class,new ReceiptEntity.Key(scope.tenantId(),scope.companyId(),receiptId));if(receipt==null||!receipt.branchId.equals(scope.branchId()))throw new NoSuchElementException("Receipt not found");var order=find(receipt.purchaseId,true);if(q.businessDate().isBefore(receipt.businessDate))throw new IllegalArgumentException("Return cannot precede receipt");if(!em.createQuery("select i from InvoiceEntity i where i.receiptId=:r",InvoiceEntity.class).setParameter("r",receiptId).getResultList().isEmpty())throw new IllegalStateException("Invoiced supplier returns require supplier credit-note workflow");
 var r=new SupplierReturnEntity();r.tenantId=scope.tenantId();r.companyId=scope.companyId();r.branchId=scope.branchId();r.id=UUID.randomUUID();r.receiptId=receiptId;r.operationId=q.operationId();r.actorId=scope.actorId();r.businessDate=q.businessDate();r.reason=q.reason();var pending=new ArrayList<SupplierReturnLineEntity>();var seen=new HashSet<UUID>();
 for(var request:q.lines()){if(request==null||!seen.add(request.receiptLineId()))throw new IllegalArgumentException("Unique returned receipt lines required");var original=em.find(ReceiptLineEntity.class,new ReceiptLineEntity.Key(scope.tenantId(),scope.companyId(),request.receiptLineId()));if(original==null||!original.receiptId.equals(receiptId))throw new IllegalArgumentException("Return line must reference selected receipt");long prior=em.createQuery("select coalesce(sum(l.quantityMilli),0) from SupplierReturnLineEntity l where l.receiptLineId=:id",Long.class).setParameter("id",original.id).getSingleResult();long qty=PurchaseRules.positive(request.quantityMilli());PurchaseRules.receive(original.quantityMilli,prior,qty);var value=java.math.BigInteger.valueOf(original.valueXaf).multiply(java.math.BigInteger.valueOf(qty)).divideAndRemainder(java.math.BigInteger.valueOf(original.quantityMilli));if(value[1].signum()!=0)throw new IllegalArgumentException("Return valuation not exactly representable in FCFA");long cost=value[0].longValueExact();var issued=stock.issue(order.warehouseId,original.productId,qty,UUID.nameUUIDFromBytes((q.operationId()+":"+original.id).getBytes(StandardCharsets.UTF_8)),q.reason());if(issued.valueXaf()!=cost)throw new IllegalStateException("Current weighted cost differs from original receipt; approved valuation adjustment required");var l=new SupplierReturnLineEntity();l.tenantId=r.tenantId;l.companyId=r.companyId;l.branchId=r.branchId;l.id=UUID.randomUUID();l.returnId=r.id;l.receiptLineId=original.id;l.productId=original.productId;l.quantityMilli=qty;l.valueXaf=cost;r.totalXaf=Math.addExact(r.totalXaf,cost);pending.add(l);}
 em.persist(r);em.flush();pending.forEach(em::persist);finance.post(r.id,q.operationId(),r.businessDate,"SUPPLIER_RETURN",List.of(new FinanceService.Entry("GOODS_RECEIVED_NOT_INVOICED",r.totalXaf,0),new FinanceService.Entry("MERCHANT_INVENTORY",0,r.totalXaf)));em.flush();return returnView(r);},SupplierReturn::id));}

}